SELECT "department" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.department", "sub_department" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.sub_department", "account_group" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.account_group", "account_id" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.account_id", "account_name" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.account_name", "cost_center" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.cost_center", "project_code" AS "e1fbe2bf-2189-4f5a-9126-7353b16121c2.project_code"
